    "chapter": "normal-dev",
    "stem": "Gerald is a 16-month-old boy who has not yet said his first word and does not babble much. His mother believes he does not hear well because he does not startle when a door slams or show any response to his name. His development is otherwise normal. Which test would be best to assess Gerald’s hearing? Select one answer only.",
