    "stem": "Evie is a 10-day-old infant and was born in London. Her health visitor reviews the family at home. She is feeding well and has a normal examination except that she has a squint. The health visitor tells her parents that she will keep this under review. At what age does Evie need to be referred for further review if the squint is still present? Select one answer only.",
