    "stem": "Andrew is a 5-year-old boy. His father feels his behaviour has deteriorated and he is worried he is not hearing him all the time. He has poor articulation of the few words that he can say. Andrew goes to the audiology department and has his hearing tested. His audiogram is shown in Fig. 4.1. What type of hearing loss does he have? Select one answer only.",
