    "stem": "Choose from the options which best describes the reason for the doctor’s actions in managing Tolla, an 11-year-old girl who has recently arrived in the UK with her mother. They are originally from Uganda. Tolla has been admitted to the paediatric ward with a chest infection. Her mother is HIV (Human immunodeficiency virus) positive but has not told any of her family members. Her husband, Tolla’s father, died of an acquired immune deficiency syndrome-related illness 6 months ago. Tolla has been tested for HIV and her test result has come back positive. Her mother does not wish her to be told, as she is still very upset about the death of Tolla’s father. Each option [A–H] may be used once, more than once, or not at all. As Tolla’s doctor you feel she should be told she is HIV positive, as you will be able to offer her more support and coping strategies if she knows more about her diagnosis.",
