    "module": "pediatrics",
    "chapter": "accidents",
    "stem": "For each of the following patients select the most likely poison from the following list (A–J). Each option may be used once, more than once, or not at all. Jacob is a 15-year-old boy who is brought to hospital by ambulance. He was found in the local park by paramedics after one of his friends phoned them to say he was in trouble. When the paramedics arrived there was no one else with him. He is not coherent and unable to walk. His blood glucose level is low.",
