    "answer": 8,
    "explanation": "I. Staphylococcal scalded skin syndrome This is staphylococcal scalded skin syndrome, caused by an exfoliative staphylococcal toxin which causes separation of the epidermal skin through the granular cell layers. This affects infants and young children. They develop fever and malaise, may have a purulent, crusting, localized infection around the eyes, nose, and mouth with subsequent widespread erythema and tenderness of the skin. Areas of epidermis separate on gentle pressure (Nikolsky’s sign) leaving denuded areas of skin, as shown here, which subsequently dry and heal without scarring.",
    "objective": "Test Bacterial infections and Kawasaki, including child protection (outside the course list: child protection).",
