    "bank": "selfassess",
    "module": "pediatrics",
    "chapter": "perinatal",
    "stem": "In the UK all newborn babies have a heel-prick blood sample taken at 5–7 days of age for biochemical screening. Which of the following is not tested for in the UK? Select one answer only.",
    "options": [
      "Cystic fibrosis",
      "Duchenne muscular dystrophy",
      "Hypothyroidism",
      "Phenylketonuria",
      "Sickle cell disease"
    ],
    "answer": 1,
    "explanation": "A. Cystic fibrosis This is now screened for in the UK. B. Duchenne muscular dystrophy Correct. This is not routinely screened for. Screening with creatine kinase measurement is unreliable at this age, with many false-positive and false-negative results, and there is insufficient evidence of long-term benefit of diagnosis in the newborn period. C. Hypothyroidism Thyroid function is screened. As this is with TSH in the UK, it may miss the rare cases of central hypothyroidism. D. Phenylketonuria This was the initial disorder screened for and was called the Guthrie test. E. Sickle cell disease This forms part of the newborn screen in the UK.",
    "objective": "Test The newborn and prematurity, including Genetics.",
    "source": "Self Assessment Book.pdf p.63 10.10"
