    "id": "pedsa-b11-6",
    "bank": "selfassess",
    "module": "pediatrics",
    "chapter": "perinatal",
    "stem": "Aaron was born at term, birth weight 3.2 kg. He is now 2 weeks old, and his mother is concerned that his umbilicus looks abnormal. A photo is shown in Fig. 11.2. Select the most likely diagnosis. Select one answer only.",
    "options": [
      "Exomphalos",
      "Gastroschisis",
      "Umbilical granuloma",
      "Umbilical hernia",
      "Umbilical infection (omphalitis)"
    ],
    "answer": 2,
    "explanation": "A. Exomphalos In exomphalos the abdominal contents protrude through the umbilical ring, covered by the amniotic membrane and peritoneum. B. Gastroschisis In gastroschisis the bowel protrudes through a defect in the anterior abdominal wall adjacent to the umbilicus. C. Umbilical granuloma Correct. In umbilical granuloma there is a pink, pedunculated lesion of granulation tissue as shown here. D. Umbilical hernia In umbilical hernia there is protrusion of the umbilicus. These are common and resolve spontaneously. E. Umbilical infection (omphalitis) In umbilical infection (omphalitis) there is redness of the skin surrounding the umbilicus, with spread of the redness onto the anterior abdominal wall (umbilical flare). Sometimes there is purulent discharge, although an umbilical granuloma can also be ‘sticky’ as it produces mucus.",
    "objective": "Test The newborn and prematurity.",
    "source": "Self Assessment Book.pdf p.70 11.6",
    "image": "q-pd-sa-70",
    "imgAlt": "Clinical photograph of the abdomen, close-up"
