    "stem": "The following is a list (A–J) of congenital heart problems encountered in children. From the list select the most likely diagnosis given the associated findings on clinical examination. The site and heart sounds and murmurs are depicted below in Fig. 18.1. For each presentation, select the most likely diagnosis. 18.6.2",
