    "module": "pediatrics",
    "chapter": "infection",
    "stem": "Joseph is a 4-year-old boy who is brought to the general paediatric clinic with this lesion in his hair (see Fig. 25.5 below). What is the most likely diagnosis? Select one answer only.",
