    "explanation": "L. Tumour – osteoid osteoma Craig may have a benign tumour, an osteoid osteoma. It presents with back pain, which is worse at night. Back pain in young children must be taken seriously, as it is uncommon. Red flag features include a young age, waking at night, fever, weight loss and focal neurological signs. Osteomyelitis of the back can occur and would present with pain but is usually associated with a fever, systemic upset and tenderness over the area.",
