    "answer": 4,
    "explanation": "A. Denmark In 2014 Denmark had the lowest rate of motherhood in the European Union area with rates of 1.1 per 1000 women aged 15–17 years. B. France France has a relatively low rate of motherhood with approximately 4.4 births per 1000 young women aged 15–17 in 2014. C. Portugal Portugal has reduced rates of motherhood in those under the age of 18 consistently over the last decade and still has rates lower than in the UK. In 2014 these were 5.3 per 1000. D. Spain Spain has been consistently one of the better performers in the European Union. Rates remain low but not as low as the Nordic countries and the Netherlands. E. United Kingdom Correct. In 2014 there were 6.8 live births per 1000 young women aged 15–17 in the UK. The highest rates were seen in Bulgaria and Romania with rates of 35.5 per 1000 and 28.2 per 1000 respectively. Data can be found at http://www.ons.gov.uk/ons/ dcp171778_353922.pdf for data on conceptions and http://www.ons.gov.uk/ons/rel/vsob1/ births-by-area-of-usual-residence-of-mother –england-and-wales/2012/sty-international -comparisons-of-teenage-pregnancy.html for most up to date statistics (Published February 2014).",
    "objective": "Test Puberty, including adolescent medicine (outside the course list: adolescent medicine).",
    "source": "Self Assessment Book.pdf p.183 30.1"
