    "module": "pediatrics",
    "chapter": "accidents",
    "stem": "Which of the following causes of death in childhood is likely to increase most in the next 15 years? Select one answer only.",
    "options": [
      "HIV infection",
      "Malaria",
      "Malnutrition",
      "Pneumonia",
      "Trauma"
    ],
    "answer": 4,
    "explanation": "A. HIV infection Death in children from HIV infection should not increase because of prevention of mother to child transmission and increasing availability and efficacy of treatment. B. Malaria Mortality from malaria is decreasing because of insecticide-treated bed nets, mosquito control, and early treatment, often by community health workers. C. Malnutrition Food poverty is an important problem but it is not predicted to increase. D. Pneumonia Pneumonia is a major cause of death during childhood. It is particularly important in younger children but is not increasing. E. Trauma Correct. Mortality from unintentional injury, mainly through road traffic incidents, is predicted to increase.",
    "objective": "Test Accidents and poisoning, including global child health (outside the course list: global child health).",
    "source": "Self Assessment Book.pdf p.186 31.3"
